INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b445d1de-dfc9-5445-bd43-714a348f809e', 'China Notice on Issuing the Green Bond Endorsed Projects', 'Notice on Issuing the Green Bond Endorsed Projects Catalogue', 'The "Green Bond Endorsed Projects Catalogue (2021 Edition)" serves as a guiding framework to promote the development of green finance in China by providing clear definitions of projects eligible for green bond funding. Jointly developed by the People’s Bank of China, the National Development and Reform Commission, and the China Securities Regulatory Commission, the policy outlines categories of projects that support environmental sustainability, including energy conservation, pollution prevention, resource conservation, and ecological protection. Specific project areas include renewable energy, green urban infrastructure, clean transportation, and sustainable water management. The catalogue emphasizes compliance with updated technical standards and encourages alignment with international green finance practices. The policy aims to reduce carbon emissions, foster industrial upgrades, and support China’s broader ecological and economic sustainability goals.', 'The "Green Bond Endorsed Projects Catalogue (2021 Edition)" serves as a guiding framework to promote the development of green finance in China by providing clear definitions of projects eligible for green bond funding. Jointly developed by the People’s Bank of China, the National Development and Reform Commission, and the China Securities Regulatory Commission, the policy outlines categories of projects that support environmental sustainability, including energy conservation, pollution prevention, resource conservation, and ecological protection. Specific project areas include renewable energy, green urban infrastructure, clean transportation, and sustainable water management. The catalogue emphasizes compliance with updated technical standards and encourages alignment with international green finance practices. The policy aims to reduce carbon emissions, foster industrial upgrades, and support China’s broader ecological and economic sustainability goals.', 'The "Green Bond Endorsed Projects Catalogue (2021 Edition)" serves as a guiding framework to promote the development of green finance in China by providing clear definitions of projects eligible for green bond funding. Jointly developed by the People’s Bank of China, the National Development and Reform Commission, and the China Securities Regulatory Commission, the policy outlines categories of projects that support environmental sustainability, including energy conservation, pollution prevention, resource conservation, and ecological protection. Specific project areas include renewable energy, green urban infrastructure, clean transportation, and sustainable water management. The catalogue emphasizes compliance with updated technical standards and encourages alignment with international green finance practices. The policy aims to reduce carbon emissions, foster industrial upgrades, and support China’s broader ecological and economic sustainability goals.', 'China', 'climate', 'in_force', '2015-01-01'::date, 'China', 'https://www.carrotsandsticks.org/policies/33_36', ARRAY['sdg13', 'regulations', 'sdg7', 'sdg11', 'china', 'mandatory', 'sdg6', 'sdg12', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ae6f73f2-3952-5582-813c-74ab880436a6', 'China Guiding Opinions on Strengthening the Construction of Enterprise', 'Guiding Opinions on Strengthening the Construction of Enterprise Environmental Credit System', 'To promote the construction of the social credit system in order to accelerate the establishment of the corporate environmental credit-keeping incentive and untrustworthy punishment mechanism, the following opinions are hereby offered for strengthening the construction of the corporate environmental credit system.', 'To promote the construction of the social credit system in order to accelerate the establishment of the corporate environmental credit-keeping incentive and untrustworthy punishment mechanism, the following opinions are hereby offered for strengthening the construction of the corporate environmental credit system.', 'To promote the construction of the social credit system in order to accelerate the establishment of the corporate environmental credit-keeping incentive and untrustworthy punishment mechanism, the following opinions are hereby offered for strengthening the construction of the corporate environmental credit system.', 'China', 'climate', 'in_force', '2015-01-01'::date, 'China', 'https://www.carrotsandsticks.org/policies/33_63', ARRAY['sdg7', 'china', 'mandatory', 'mandatory_regulations', 'sdg12', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('926d0944-2531-5aa6-bf72-bb5f5148dc18', 'China Technical specification for prevention and control of occupational', 'Technical specification for prevention and control of occupational hazards in construction enterprise', 'This standard specifies the technical measures and management requirements for the prevention and control of occupational disease hazards in construction enterprises.', 'This standard specifies the technical measures and management requirements for the prevention and control of occupational disease hazards in construction enterprises.', 'This standard specifies the technical measures and management requirements for the prevention and control of occupational disease hazards in construction enterprises.', 'China', 'nature', 'in_force', '2015-01-01'::date, 'China', 'https://www.carrotsandsticks.org/policies/33_88', ARRAY['sdg8', 'sdg14', 'mandatory', 'mandatory_regulations', 'disclosure', 'china', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('278eabb5-f5f7-5d48-85a0-3d6357187b71', 'China Environmental Protection Law', 'Environmental Protection Law of the People''s Republic of China', 'This Law is formulated for the purpose of protecting and improving the environment, preventing and controlling pollution and other public hazards, safeguarding public health, promoting the construction of ecological civilization, and promoting sustainable economic and social development.', 'This Law is formulated for the purpose of protecting and improving the environment, preventing and controlling pollution and other public hazards, safeguarding public health, promoting the construction of ecological civilization, and promoting sustainable economic and social development.', 'This Law is formulated for the purpose of protecting and improving the environment, preventing and controlling pollution and other public hazards, safeguarding public health, promoting the construction of ecological civilization, and promoting sustainable economic and social development.', 'China', 'governance', 'in_force', '2014-01-01'::date, 'China', 'https://www.carrotsandsticks.org/policies/33_49', ARRAY['regulations', 'china', 'mandatory', 'disclosure', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2c065011-431c-5bd3-9f42-c78661372c6f', 'China Interim Regulation on Enterprise Information Publicity', 'Interim Regulation on Enterprise Information Publicity', 'A regulation to ensure fair competition, promote corporate integrity and self-discipline, regulate corporate information disclosure, strengthen corporate credit constraints, maintain transaction security, improve government supervision efficiency, and expand social supervision.', 'A regulation to ensure fair competition, promote corporate integrity and self-discipline, regulate corporate information disclosure, strengthen corporate credit constraints, maintain transaction security, improve government supervision efficiency, and expand social supervision.', 'A regulation to ensure fair competition, promote corporate integrity and self-discipline, regulate corporate information disclosure, strengthen corporate credit constraints, maintain transaction security, improve government supervision efficiency, and expand social supervision.', 'China', 'governance', 'in_force', '2014-01-01'::date, 'China', 'https://www.carrotsandsticks.org/policies/33_65', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'china']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7bb456eb-11cd-5b5e-96c7-6c8fdeb3c352', 'China Measures for the Disclosure of Environmental Information', 'Measures for the Disclosure of Environmental Information of Enterprises and Institutions', 'A measure to safeguard the rights of citizens, legal persons and other organizations to obtain environmental information in accordance with the law, to promote enterprises and institutions to truthfully disclose environmental information to the public, and to promote public participation and supervision of environmental protection.', 'A measure to safeguard the rights of citizens, legal persons and other organizations to obtain environmental information in accordance with the law, to promote enterprises and institutions to truthfully disclose environmental information to the public, and to promote public participation and supervision of environmental protection.', 'A measure to safeguard the rights of citizens, legal persons and other organizations to obtain environmental information in accordance with the law, to promote enterprises and institutions to truthfully disclose environmental information to the public, and to promote public participation and supervision of environmental protection.', 'China', 'social', 'in_force', '2014-01-01'::date, 'China', 'https://www.carrotsandsticks.org/policies/33_73', ARRAY['china', 'mandatory', 'regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('51ba3679-a12c-58de-8e1c-d243640fb083', 'China Notice of the General Office of the State', 'Notice of the General Office of the State Council on Strengthening Environmental Supervision and Law Enforcement', 'A notice to implement the spirit of the Fourth Plenary Session of the 18th Central Committee of the Communist Party of China and the relevant decisions and arrangements of the Party Central Committee and the State Council, speed up the resolution of prominent environmental problems that affect scientific development and harm the health of the people, and strive to improve environmental quality.', 'A notice to implement the spirit of the Fourth Plenary Session of the 18th Central Committee of the Communist Party of China and the relevant decisions and arrangements of the Party Central Committee and the State Council, speed up the resolution of prominent environmental problems that affect scientific development and harm the health of the people, and strive to improve environmental quality.', 'A notice to implement the spirit of the Fourth Plenary Session of the 18th Central Committee of the Communist Party of China and the relevant decisions and arrangements of the Party Central Committee and the State Council, speed up the resolution of prominent environmental problems that affect scientific development and harm the health of the people, and strive to improve environmental quality.', 'China', 'climate', 'in_force', '2014-01-01'::date, 'China', 'https://www.carrotsandsticks.org/policies/33_77', ARRAY['regulations', 'sdg7', 'china', 'mandatory', 'sdg12', 'disclosure', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('157a056d-cc75-5cb6-aef0-ad234ac89d0f', 'China Circular of the State Council on Printing', 'Circular of the State Council on Printing and Distributing the Outline of the Plan for the Construction of the Social Credit System (2014-2020)', 'This instrument seeks to establish and improve the social credit reporting system, praise integrity and punish dishonesty. It further seeks to accelerate the construction of the social credit system is an important foundation for fully implementing the scientific concept of development and building a harmonious socialist society. It is an important means to improve the socialist market economic system and strengthen and innovate social governance. It is of great significance to enhance the overall competitiveness of the country and promote social development and civilization progress.', 'This instrument seeks to establish and improve the social credit reporting system, praise integrity and punish dishonesty. It further seeks to accelerate the construction of the social credit system is an important foundation for fully implementing the scientific concept of development and building a harmonious socialist society. It is an important means to improve the socialist market economic system and strengthen and innovate social governance. It is of great significance to enhance the overall competitiveness of the country and promote social development and civilization progress.', 'This instrument seeks to establish and improve the social credit reporting system, praise integrity and punish dishonesty. It further seeks to accelerate the construction of the social credit system is an important foundation for fully implementing the scientific concept of development and building a harmonious socialist society. It is an important means to improve the socialist market economic system and strengthen and innovate social governance. It is of great significance to enhance the overall competitiveness of the country and promote social development and civilization progress.', 'China', 'climate', 'in_force', '2014-01-01'::date, 'China', 'https://www.carrotsandsticks.org/policies/33_85', ARRAY['sdg4', 'sdg17', 'mandatory', 'sdg16', 'mandatory_regulations', 'sdg12', 'disclosure', 'china']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c0671851-9e4a-572b-b12d-875b20aad8af', 'China Accounting Methods and Reporting of Greenhouse Gas Emissions', 'Guidelines for Accounting Methods and Reporting of Greenhouse Gas Emissions of Chinese Cement Manufacturers (Trial)', 'Guidelines to help companies scientifically account for and report their own greenhouse gas emissions, better formulate corporate greenhouse gas emission control plans or carbon emissions trading strategies, actively participate in carbon emissions trading, and strengthen corporate social responsibility. At the same time, it also lays the foundation for the competent authorities to establish and implement the greenhouse gas reporting system of key enterprises, and provides support for grasping the greenhouse gas emissions of key enterprises and formulating relevant policies.', 'Guidelines to help companies scientifically account for and report their own greenhouse gas emissions, better formulate corporate greenhouse gas emission control plans or carbon emissions trading strategies, actively participate in carbon emissions trading, and strengthen corporate social responsibility. At the same time, it also lays the foundation for the competent authorities to establish and implement the greenhouse gas reporting system of key enterprises, and provides support for grasping the greenhouse gas emissions of key enterprises and formulating relevant policies.', 'Guidelines to help companies scientifically account for and report their own greenhouse gas emissions, better formulate corporate greenhouse gas emission control plans or carbon emissions trading strategies, actively participate in carbon emissions trading, and strengthen corporate social responsibility. At the same time, it also lays the foundation for the competent authorities to establish and implement the greenhouse gas reporting system of key enterprises, and provides support for grasping the greenhouse gas emissions of key enterprises and formulating relevant policies.', 'China', 'climate', 'in_force', '2013-01-01'::date, 'China', 'https://www.carrotsandsticks.org/policies/33_52', ARRAY['sdg13', 'regulations', 'china', 'sdg12', 'disclosure', 'sdg9', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
