INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('22f8e048-4ba2-581c-b5d8-1879f9a03045', 'China Measures for Enterprise Environmental Credit Evaluation (Trial)', 'Measures for Enterprise Environmental Credit Evaluation (Trial)', 'A measure to actively promote the environmental credit evaluation of enterprises, urge enterprises to consciously fulfil their legal obligations and social responsibilities in environmental protection, and guide the public to participate in environmental supervision, promote the coordination and cooperation of relevant departments, and accelerate the establishment of "trustworthy incentives and untrustworthy punishments" for environmental protection. mechanism to promote the construction of the social credit system.', 'A measure to actively promote the environmental credit evaluation of enterprises, urge enterprises to consciously fulfil their legal obligations and social responsibilities in environmental protection, and guide the public to participate in environmental supervision, promote the coordination and cooperation of relevant departments, and accelerate the establishment of "trustworthy incentives and untrustworthy punishments" for environmental protection. mechanism to promote the construction of the social credit system.', 'A measure to actively promote the environmental credit evaluation of enterprises, urge enterprises to consciously fulfil their legal obligations and social responsibilities in environmental protection, and guide the public to participate in environmental supervision, promote the coordination and cooperation of relevant departments, and accelerate the establishment of "trustworthy incentives and untrustworthy punishments" for environmental protection. mechanism to promote the construction of the social credit system.', 'China', 'governance', 'in_force', '2013-01-01'::date, 'China', 'https://w