INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('39b61dee-396a-523f-9c1d-158f6f9e075c', 'China Notice on Printing and Distributing "Measures for Self-Monitoring', 'Notice on Printing and Distributing "Measures for Self-Monitoring and Information Disclosure of National Key Monitoring Enterprises  […]', 'A notice to establish and improve the pollution source monitoring and information disclosure system. To urge enterprises to fulfil their responsibilities and obligations, and carry out self-monitoring; further standardize the supervision and monitoring of environmental protection departments, and promote the disclosure of pollution source monitoring information.', 'A notice to establish and improve the pollution source monitoring and information disclosure system. To urge enterprises to fulfil their responsibilities and obligations, and carry out self-monitoring; further standardize the supervision and monitoring of environmental protection departments, and promote the disclosure of pollution source monitoring information.', 'A notice to establish and improve the pollution source monitoring and information disclosure system. To urge enterprises to fulfil their responsibilities and obligations, and carry out self-monitoring; further standardize the supervision and monitoring of environmental protection departments, and promote the disclosure of pollution source monitoring information.', 'China', 'governance', 'in_force', '2013-01-01'::date, 'China', 'https://www.carrotsandsticks.org/policies/33_76', ARRAY['china', 'mandatory', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('fd330070-d234-5925-8c0b-775afb20c001', 'China Decision of the Standing Committee of the National', 'Decision of the Standing Committee of the National People''s Congress on Amending the Cleaner Production Promotion Law of the People''s Republic of China', 'This decision sets out to promote cleaner production, improve resource utilization efficiency, reduce and avoid the generation of pollutants, protect and improve the environment, safeguard human health, and promote sustainable economic and social development.', 'This decision sets out to promote cleaner production, improve resource utilization efficiency, reduce and avoid the generation of pollutants, protect and improve the environment, safeguard human health, and promote sustainable economic and social development.', 'This decision sets out to promote cleaner production, improve resource utilization efficiency, reduce and avoid the generation of pollutants, protect and improve the environment, safeguard human health, and promote sustainable economic and social development.', 'China', 'circularity', 'in_force', '2012-01-01'::date, 'China', 'https://www.carrotsandsticks.org/policies/33_37', ARRAY['regulations', 'china', 'mandatory', 'sdg12', 'disclosure', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('648fda9a-94bc-57b7-9dc7-b497c3e1dc71', 'China Green Credit Guidelines (绿色信贷指引)', 'Green Credit Guidelines (绿色信贷指引)', 'The Green Credit Guidelines, issued by the China Banking and Insurance Regulatory Commission (CBIRC) in 2012, establish a framework for banks and financial institutions to incorporate environmental and social risk management into their lending activities. The guidelines aim to promote sustainable finance, support low-carbon economic development, and prevent financial risks associated with environmental and social issues.
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('60f678a4-8e8a-568f-bcd1-959202dd43c3', 'China Measures for Administration of Information Disclosure by Insurance', 'Measures for Administration of Information Disclosure by Insurance Companies', 'A measure to regulate the information disclosure of insurance companies, protect the legitimate rights and interests of policy holders, insurers, and beneficiaries, and promote the healthy development of the insurance industry.', 'A measure to regulate the information disclosure of insurance companies, protect the legitimate rights and interests of policy holders, insurers, and beneficiaries, and promote the healthy development of the insurance industry.', 'A measure to regulate the information disclosure of insurance companies, protect the legitimate rights and interests of policy holders, insurers, and beneficiaries, and promote the healthy development of the insurance industry.', 'China', 'governance', 'in_force', '2010-01-01'::date, 'China', 'https://www.carrotsandsticks.org/policies/33_70', ARRAY['sdg9', 'mandatory', 'mandatory_regulations', 'disclosure', 'china', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('45f2d1bb-c3c4-5ba1-82c8-d359c659fc84', 'China Guidance Opinions on Strenghthening the Environmental Supervision', 'Guidance Opinions on Strenghthening the Environmental Supervision of Listed Companies', 'To guide listed companies to actively fulfil their social responsibilities for environmental protection, and to promote listed companies to continuously improve their environmental performance , striving to be a resource-saving and environment-friendly model.', 'To guide listed companies to actively fulfil their social responsibilities for environmental protection, and to promote listed companies to continuously improve their environmental performance , striving to be a resource-saving and environment-friendly model.', 'To guide listed companies to actively fulfil their social responsibilities for environmental protection, and to promote listed companies to continuously improve their environmental performance , striving to be a resource-saving and environment-friendly model.', 'China', 'climate', 'in_force', '2008-01-01'::date, 'China', 'https://www.carrotsandsticks.org/policies/33_14', ARRAY['guidance_frameworks', 'sdg7', 'china', 'mandatory', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
