INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9c88d521-9424-5f29-aa18-49f2764d8165', 'China Social Responsibility Guidelines for Chinese Industrial Enterprises', 'Social Responsibility Guidelines for Chinese Industrial Enterprises and Industrial Associations', 'These guidelines advocate and promot the fulfilment of social responsibility by industrial enterprises and industrial associations, and jointly building a harmonious socialist society.', 'These guidelines advocate and promot the fulfilment of social responsibility by industrial enterprises and industrial associations, and jointly building a harmonious socialist society.', 'These guidelines advocate and promot the fulfilment of social responsibility by industrial enterprises and industrial associations, and jointly building a harmonious socialist society.', 'China', 'climate', 'in_force', '2008-01-01'::date, 'China', 'https://www.carrotsandsticks.org/policies/33_29', ARRAY['guidance_frameworks', 'sdg9', 'disclosure', 'china', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6b55842d-958d-5acb-955f-f80c6cb3742f', 'China Law on the Prevention and Control of Water', 'Law of the People''s Republic of China on the Prevention and Control of Water Pollution', 'This standard applies to the design, construction, acceptance, operation and occupational health management of technical measures for the prevention and control of occupational disease hazards such as dustproof, anti-virus, anti-noise, high-temperature and low-temperature protection, radiation protection, and emergency disposal in construction enterprises.', 'This standard applies to the design, construction, acceptance, operation and occupational health management of technical measures for the prevention and control of occupational disease hazards such as dustproof, anti-virus, anti-noise, high-temperature and low-temperature protection, radiation protection, and emergency disposal in construction enterprises.', 'This standard applies to the design, construction, acceptance, operation and occupational health management of technical measures for the prevention and control of occupational disease hazards such as dustproof, anti-virus, anti-noise, high-temperature and low-temperature protection, radiation protection, and emergency disposal in construction enterprises.', 'China', 'climate', 'in_force', '2008-01-01'::date, 'China', 'https://www.carrotsandsticks.org/policies/33_89', ARRAY['sdg8', 'sdg2', 'regulations', 'china', 'sdg11', 'mandatory', 'sdg6', 'disclosure', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d42dff06-8e6f-51e9-9c1b-b280faa9e9a4', 'Energy Conservation Law of the People’s Republic of China', 'Energy Conservation Law of the People’s Republic of China', 'The law is formulated for the purposes of promoting energy conservation in the whole society, improving energy utilization efficiency, protecting and ameliorating the environment, and striving for all around, balanced and sustainable development of the economy and the society.', 'The law is formulated for the purposes of promoting energy conservation in the whole society, improving energy utilization efficiency, protecting and ameliorating the environment, and striving for all around, balanced and sustainable development of the economy and the society.', 'The law is formulated for the purposes of promoting energy conservation in the whole society, improving energy utilization efficiency, protecting and ameliorating the environment, and striving for all around, balanced and sustainable development of the economy and the society.', 'China', 'climate', 'in_force', '2007-01-01'::date, 'China', 'https://www.carrotsandsticks.org/policies/33_12', ARRAY['other sustainability policy', 'regulations', 'sdg7', 'sdg11', 'mandatory', 'china']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('388d0ffe-248e-5fab-8970-66e7803eef04', 'China Pudong New Area Corporate Social Responsibility Guidelines', 'Pudong New Area Corporate Social Responsibility Guidelines', 'These guidelines aim to promote the comprehensive supporting reform pilot, building a corporate social responsibility (CSR) system, and promoting companies to fulfil their social responsibilities. Corporate social responsibility means that in the process of business activities, while pursuing the interests of the enterprise, companies should also take into account the interests of stakeholders who are closely related to the behaviour of the company and the society, so as to realize the sustainable development of the company and build a harmonious society and Corporate social responsibility.', 'These guidelines aim to promote the comprehensive supporting reform pilot, building a corporate social responsibility (CSR) system, and promoting companies to fulfil their social responsibilities. Corporate social responsibility means that in the process of business activities, while pursuing the interests of the enterprise, companies should also take into account the interests of stakeholders who are closely related to the behaviour of the company and the society, so as to realize the sustainable development of the company and build a harmonious society and Corporate social responsibility.', 'These guidelines aim to promote the comprehensive supporting reform pilot, building a corporate social responsibility (CSR) system, and promoting companies to fulfil their social responsibilities. Corporate social responsibility means that in the process of business activities, while pursuing the interests of the enterprise, companies should also take into account the interests of stakeholders who are closely related to the behaviour of the company and the society, so as to realize the sustainable development of the company and build a harmonious society and Corporate social responsibility.', 'China', 'climate', 'in_force', '2007-01-01'::date, 'China', 'https://www.carrotsandsticks.org/policies/33_22', ARRAY['guidance_frameworks', 'sdg13', 'sdg16', 'sdg12', 'disclosure', 'china', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1f0904ef-485b-58a1-ab33-8cc2d2bd11f5', 'China Measures for the Disclosure of Environmental Information (for', 'Measures for the Disclosure of Environmental Information (for Trial Implementation)', 'A measure to promote and standardize environmental protection administrative departments (hereinafter referred to as environmental protection departments) and enterprises to disclose environmental information, safeguard the rights and interests of citizens, legal persons and other organizations to obtain environmental information, and promote public participation in environmental protection.', 'A measure to promote and standardize environmental protection administrative departments (hereinafter referred to as environmental protection departments) and enterprises to disclose environmental information, safeguard the rights and interests of citizens, legal persons and other organizations to obtain environmental information, and promote public participation in environmental protection.', 'A measure to promote and standardize environmental protection administrative departments (hereinafter referred to as environmental protection departments) and enterprises to disclose environmental information, safeguard the rights and interests of citizens, legal persons and other organizations to obtain environmental information, and promote public participation in environmental protection.', 'China', 'circularity', 'in_force', '2007-01-01'::date, 'China', 'https://www.carrotsandsticks.org/policies/33_72', ARRAY['china', 'mandatory', 'mandatory_regulations', 'sdg12', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b32e38bb-c7a5-532f-9059-320791114ecf', 'China Production Safety Accident Reporting, Investigation and Handling Regulations', 'Production Safety Accident Reporting, Investigation and Handling Regulations', 'The purpose of this instrument is to regulate the reporting, investigation and handling of production safety accidents, implement the accountability system for production safety accidents, and prevent and reduce production safety accidents.', 'The purpose of this instrument is to regulate the reporting, investigation and handling of production safety accidents, implement the accountability system for production safety accidents, and prevent and reduce production safety accidents.', 'The purpose of this instrument is to regulate the reporting, investigation and handling of production safety accidents, implement the accountability system for production safety accidents, and prevent and reduce production safety accidents.', 'China', 'climate', 'in_force', '2007-01-01'::date, 'China', 'https://www.carrotsandsticks.org/policies/33_80', ARRAY['regulations', 'mandatory', 'sdg16', 'sdg12', 'disclosure', 'china']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('42ef11d0-0473-5728-801d-c79a9f3728c9', 'China Securities Law', 'Securities Law of the People''s Republic of China', 'This law sets out to regulate securities issuance and trading, protect the legitimate rights and interests of investors, maintain social and economic order and social public interests, and promote the development of the socialist market economy.', 'This law sets out to regulate securities issuance and trading, protect the legitimate rights and interests of investors, maintain social and economic order and social public interests, and promote the development of the socialist market economy.', 'This law sets out to regulate securities issuance and trading, protect the legitimate rights and interests of investors, maintain social and economic order and social public interests, and promote the development of the socialist market economy.', 'China', 'governance', 'in_force', '2006-01-01'::date, 'China', 'https://www.carrotsandsticks.org/policies/33_82', ARRAY['regulations', 'china', 'mandatory', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f4560269-8b3b-5dc1-a12d-4695e9c9911e', 'China Measures for Administration of Information Reporting and Disclosure', 'Measures for Administration of Information Reporting and Disclosure of Direct Selling Companies', 'A measure mandating that direct selling enterprises shall establish a complete information reporting and disclosure system, and accept the supervision and inspection of relevant government departments and the supervision of the public.', 'A measure mandating that direct selling enterprises shall establish a complete information reporting and disclosure system, and accept the supervision and inspection of relevant government departments and the supervision of the public.', 'A measure mandating that direct selling enterprises shall establish a complete information reporting and disclosure system, and accept the supervision and inspection of relevant government departments and the supervision of the public.', 'China', 'climate', 'in_force', '2005-01-01'::date, 'China', 'https://www.carrotsandsticks.org/policies/33_69', ARRAY['china', 'mandatory', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4c9ebc59-ec3b-59d6-8a53-50fccb6eee51', 'China Provisional Code of Corporate Governance for Securities Companies', 'Provisional Code of Corporate Governance for Securities Companies', 'This document promotes the view to standardizing the operations of securities companies in line with the modern enterprise system, ensuring the legitimate interests of the shareholders, clients and other interested parties of the securities companies, and safeguarding the independence and integrity of the securities companies’ assets.', 'This document promotes the view to standardizing the operations of securities companies in line with the modern enterprise system, ensuring the legitimate interests of the shareholders, clients and other interested parties of the securities companies, and safeguarding the independence and integrity of the securities companies’ assets.', 'This document promotes the view to standardizing the operations of securities companies in line with the modern enterprise system, ensuring the legitimate interests of the shareholders, clients and other interested parties of the securities companies, and safeguarding the independence and integrity of the securities companies’ assets.', 'China', 'governance', 'in_force', '2003-01-01'::date, 'China', 'https://www.carrotsandsticks.org/policies/33_18', ARRAY['other sustainability policy', 'mandatory', 'sdg16', 'mandatory_regulations', 'china']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a0aea996-679f-5460-833b-49c6f81c941a', 'China Law on Work Safety', 'Law of the People''s Republic of China on Work Safety', 'This law is for enhancing supervision and control over work safety, preventing accidents due to lack of work safety and keeping their occurrence at a lower level, ensuring the safety of people’s lives and property and promoting the development of the economy.', 'This law is for enhancing supervision and control over work safety, preventing accidents due to lack of work safety and keeping their occurrence at a lower level, ensuring the safety of people’s lives and property and promoting the development of the economy.', 'This law is for enhancing supervision and control over work safety, preventing accidents due to lack of work safety and keeping their occurrence at a lower level, ensuring the safety of people’s lives and property and promoting the development of the economy.', 'China', 'governance', 'in_force', '2002-01-01'::date, 'China', 'https://www.carrotsandsticks.org/policies/33_90', ARRAY['china', 'mandatory', 'regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e656a187-7f81-537c-8077-3cf40b63f0dc', 'Code of Corporate Governance for Listed Companies in China', 'Code of Corporate Governance for Listed Companies in China', 'To deliver on the vision of innovative, coordinated, green and open development for all, promote entrepreneurship, fulfil social responsibilities, and develop good corporate governance practices.', 'To deliver on the vision of innovative, coordinated, green and open development for all, promote entrepreneurship, fulfil social responsibilities, and develop good corporate governance practices.', 'To deliver on the vision of innovative, coordinated, green and open development for all, promote entrepreneurship, fulfil social responsibilities, and develop good corporate governance practices.', 'China', 'governance', 'in_force', '2001-01-01'::date, 'China', 'https://www.carrotsandsticks.org/policies/33_11', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'china']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ed75164f-028e-5b34-975b-85fbc3e34daf', 'IFRS CDSB Framework for Reporting Environmental and Social Information', 'CDSB Framework for Reporting Environmental and Social Information', 'The CDSB Framework provides a standardized approach for integrating environmental and social information into mainstream financial reports, enhancing decision-useful disclosures for investors and stakeholders. It aims to align sustainability reporting with financial reporting standards, emphasizing principles such as materiality, relevance, comparability, and verifiability. The framework includes detailed guidance on reporting governance, management''s environmental and social strategies, sources of impact, performance analysis, and future outlook. Designed for global application, the framework is compatible with existing voluntary and mandatory reporting provisions, including the Task Force on Climate-related Financial Disclosures (TCFD) and Global Reporting Initiative (GRI). By offering a clear and comparable disclosure system, the CDSB Framework supports informed capital allocation, regulatory compliance, and the efficient management of environmental and social risks and opportunities.', 'The CDSB Framework provides a standardized approach for integrating environmental and social information into mainstream financial reports, enhancing decision-useful disclosures for investors and stakeholders. It aims to align sustainability reporting with financial reporting standards, emphasizing principles such as materiality, relevance, comparability, and verifiability. The framework includes detailed guidance on reporting governance, management''s environmental and social strategies, sources of impact, performance analysis, and future outlook. Designed for global application, the framework is compatible with existing voluntary and mandatory reporting provisions, including the Task Force on Climate-related Financial Disclosures (TCFD) and Global Reporting Initiative (GRI). By offering a clear and comparable disclosure system, the CDSB Framework supports informed capital allocation, regulatory compliance, and the efficient management of environmental and social risks and opportunities.', 'The CDSB Framework provides a standardized approach for integrating environmental and social information into mainstream financial reports, enhancing decision-useful disclosures for investors and stakeholders. It aims to align sustainability reporting with financial reporting standards, emphasizing principles such as materiality, relevance, comparability, and verifiability. The framework includes detailed guidance on reporting governance, management''s environmental and social strategies, sources of impact, performance analysis, and future outlook. Designed for global application, the framework is compatible with existing voluntary and mandatory reporting provisions, including the Task Force on Climate-related Financial Disclosures (TCFD) and Global Reporting Initiative (GRI). By offering a clear and comparable disclosure system, the CDSB Framework supports informed capital allocation, regulatory compliance, and the efficient management of environmental and social risks and opportunities.', 'IFRS', 'climate', 'in_force', '2022-01-01'::date, 'IFRS Foundation', 'https://www.ifrs.org/content/dam/ifrs/groups/cdsb/cdsb-framework-2022.pdf', ARRAY['sdg13', 'sdg7', 'voluntary', 'ifrs', 'sdg16', 'sdg12', 'disclosure', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2e3a4c9c-81d1-59e3-b220-2bdce4177e99', 'Colombia Addition of Chapter XV to Basic Legal Circular', 'Addition of Chapter XV to Basic Legal Circular 100-000008 of July 12, 2022', 'The Basic Legal Circular is added, in the sense of providing general instructions regarding foreign Non-Profit Entities with permanent businesses in Colombia, with the purpose of referencing their applicable regulatory, jurisprudential and doctrinal framework, considering the supervisory functions assigned for the purposes mentioned in the Political Constitution; followed by aspects related to the constitution of representatives and operation as well as matters related to the private liquidation of their businesses and assets in Colombia.', 'The Basic Legal Circular is added, in the sense of providing general instructions regarding foreign Non-Profit Entities with permanent businesses in Colombia, with the purpose of referencing their applicable regulatory, jurisprudential and doctrinal framework, considering the supervisory functions assigned for the purposes mentioned in the Political Constitution; followed by aspects related to the constitution of representatives and operation as well as matters related to the private liquidation of their businesses and assets in Colombia.', 'The Basic Legal Circular is added, in the sense of providing general instructions regarding foreign Non-Profit Entities with permanent businesses in Colombia, with the purpose of referencing their applicable regulatory, jurisprudential and doctrinal framework, considering the supervisory functions assigned for the purposes mentioned in the Political Constitution; followed by aspects related to the constitution of representatives and operation as well as matters related to the private liquidation of their businesses and assets in Colombia.', 'Colombia', 'climate', 'in_force', '2023-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_40', ARRAY['sdg16', 'mandatory', 'mandatory_regulations', 'colombia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4f6d0cea-64f3-57a1-b762-bb49f4454466', '2026 “COLOMBIA WORLD POWER OF LIFE” IS ISSUED', 'LAW 2294 OF 2023 BY WHICH THE NATIONAL DEVELOPMENT PLAN 2022-2026 “COLOMBIA WORLD POWER OF LIFE” IS ISSUED.', 'Colombia''s National Development Plan 2022-2026, enshrined in law, aims to position the country as a leader in life protection, fostering a new social contract that addresses historical injustices and promotes peace, environmental stewardship, and knowledge-based economic transformation.', 'Colombia''s National Development Plan 2022-2026, enshrined in law, aims to position the country as a leader in life protection, fostering a new social contract that addresses historical injustices and promotes peace, environmental stewardship, and knowledge-based economic transformation.', 'Colombia''s National Development Plan 2022-2026, enshrined in law, aims to position the country as a leader in life protection, fostering a new social contract that addresses historical injustices and promotes peace, environmental stewardship, and knowledge-based economic transformation.', 'Colombia', 'climate', 'in_force', '2023-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_41', ARRAY['sdg2', 'sdg13', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'sdg6', 'sdg5', 'colombia', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('600ccdb6-1d5b-5779-b4f9-c134726e1f5a', 'PHASE I FOR THE CONSTRUCTION OF THE COLOMBIAN', 'PHASE I FOR THE CONSTRUCTION OF THE COLOMBIAN GREEN TAXONOMY WHITE PAPER No. 1', 'The Green Taxonomy of Colombia is a classification system of economic activities and assets that contribute to the achievement of the country''s environmental objectives and commitments. The Taxonomy incorporates a set of definitions aimed at supporting different actors in the public and private sector, such as bond issuers, investors, financial institutions, public entities, among others, in the identification and evaluation of investments that can meet environmental and that can be considered green or environmentally sustainable in Colombia.', 'The Green Taxonomy of Colombia is a classification system of economic activities and assets that contribute to the achievement of the country''s environmental objectives and commitments. The Taxonomy incorporates a set of definitions aimed at supporting different actors in the public and private sector, such as bond issuers, investors, financial institutions, public entities, among others, in the identification and evaluation of investments that can meet environmental and that can be considered green or environmentally sustainable in Colombia.', 'The Green Taxonomy of Colombia is a classification system of economic activities and assets that contribute to the achievement of the country''s environmental objectives and commitments. The Taxonomy incorporates a set of definitions aimed at supporting different actors in the public and private sector, such as bond issuers, investors, financial institutions, public entities, among others, in the identification and evaluation of investments that can meet environmental and that can be considered green or environmentally sustainable in Colombia.', 'Colombia', 'climate', 'in_force', '2023-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_42', ARRAY['other sustainability policy', 'sdg7', 'mandatory', 'colombia', 'mandatory_regulations', 'sdg12', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ce967842-5c6f-53a0-930d-7c2e3c513871', 'Colombia Decree Number 310 of', 'Decree Number 310 of 2021', 'Decree 310 of 2021 extends the mandatory use of Framework Agreements to entities governed by the general contracting statute.', 'Decree 310 of 2021 extends the mandatory use of Framework Agreements to entities governed by the general contracting statute.', 'Decree 310 of 2021 extends the mandatory use of Framework Agreements to entities governed by the general contracting statute.', 'Colombia', 'circularity', 'in_force', '2021-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_15', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'colombia', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e641f0be-57f3-5e80-91d4-cf52604170f2', 'Colombia Presentation of Phase I for the Construction', 'Presentation of Phase I for the Construction of the Green Taxonomy Colombia 2021', 'The green taxonomy defines a classification system for economic activities and assets with substantial contributions to the achievement of environmental objectives, which respond to the commitments, strategies and policies outlined by Colombia in environmental matters.', 'The green taxonomy defines a classification system for economic activities and assets with substantial contributions to the achievement of environmental objectives, which respond to the commitments, strategies and policies outlined by Colombia in environmental matters.', 'The green taxonomy defines a classification system for economic activities and assets with substantial contributions to the achievement of environmental objectives, which respond to the commitments, strategies and policies outlined by Colombia in environmental matters.', 'Colombia', 'climate', 'in_force', '2021-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_39', ARRAY['sdg13', 'other sustainability policy', 'mandatory', 'colombia', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('feb48252-45d0-50fb-979c-b90922f865a8', 'Colombia Sectoral technical document: Energy', 'Sectoral technical document: Energy', 'The sectoral technical document on Energy in Colombia, 2021, aims to decarbonize the energy sector to transition to a low-carbon economy and mitigate climate change. It provides a taxonomy of economic activities and assets in the energy sector, exempting renewable energy activities like solar, wind, and ocean energy from GHG life cycle studies. The policy sets eligibility criteria for different energy generation technologies based on their emissions intensity, emphasizing the importance of supporting the transition to a low-carbon economy. The document targets various economic sectors to promote sustainable energy production.', 'The sectoral technical document on Energy in Colombia, 2021, aims to decarbonize the energy sector to transition to a low-carbon economy and mitigate climate change. It provides a taxonomy of economic activities and assets in the energy sector, exempting renewable energy activities like solar, wind, and ocean energy from GHG life cycle studies. The policy sets eligibility criteria for different energy generation technologies based on their emissions intensity, emphasizing the importance of supporting the transition to a low-carbon economy. The document targets various economic sectors to promote sustainable energy production.', 'The sectoral technical document on Energy in Colombia, 2021, aims to decarbonize the energy sector to transition to a low-carbon economy and mitigate climate change. It provides a taxonomy of economic activities and assets in the energy sector, exempting renewable energy activities like solar, wind, and ocean energy from GHG life cycle studies. The policy sets eligibility criteria for different energy generation technologies based on their emissions intensity, emphasizing the importance of supporting the transition to a low-carbon economy. The document targets various economic sectors to promote sustainable energy production.', 'Colombia', 'climate', 'in_force', '2021-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_43', ARRAY['sdg13', 'sdg14', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'colombia', 'sdg12', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3839b4de-d307-5969-a3d0-32d19a130185', 'Colombia Sectoral technical document: Construction', 'Sectoral technical document: Construction', 'The Sectoral technical document for Construction in Colombia outlines activities in the construction sector related to climate change mitigation and sustainable building practices. It emphasizes the importance of sustainable design and energy efficiency in new construction and renovation projects to reduce greenhouse gas emissions and promote a transition to a low-carbon economy. The document sets eligibility criteria based on energy consumption reductions and energy generation systems for buildings to comply with national sustainable construction standards.', 'The Sectoral technical document for Construction in Colombia outlines activities in the construction sector related to climate change mitigation and sustainable building practices. It emphasizes the importance of sustainable design and energy efficiency in new construction and renovation projects to reduce greenhouse gas emissions and promote a transition to a low-carbon economy. The document sets eligibility criteria based on energy consumption reductions and energy generation systems for buildings to comply with national sustainable construction standards.', 'The Sectoral technical document for Construction in Colombia outlines activities in the construction sector related to climate change mitigation and sustainable building practices. It emphasizes the importance of sustainable design and energy efficiency in new construction and renovation projects to reduce greenhouse gas emissions and promote a transition to a low-carbon economy. The document sets eligibility criteria based on energy consumption reductions and energy generation systems for buildings to comply with national sustainable construction standards.', 'Colombia', 'climate', 'in_force', '2021-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_44', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'colombia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ef76ad8e-8e52-5d90-b8df-48f4f5432f27', 'Colombia Sectoral technical document: Waste management and emissions capture', 'Sectoral technical document: Waste management and emissions capture', 'The sectoral technical document on waste management and emissions capture in Colombia outlines key activities for post-consumer waste management and greenhouse gas emissions capture essential for mitigating climate change and advancing towards a circular economy. It includes eligibility criteria for activities such as the use of non-hazardous waste material, capture and utilization of landfill gas, anaerobic digestion of organic waste, and energy production from non-recyclable waste fractions. The document aims to achieve climate goals aligned with the Paris Agreement by promoting sustainable waste management practices and reducing greenhouse gas emissions.', 'The sectoral technical document on waste management and emissions capture in Colombia outlines key activities for post-consumer waste management and greenhouse gas emissions capture essential for mitigating climate change and advancing towards a circular economy. It includes eligibility criteria for activities such as the use of non-hazardous waste material, capture and utilization of landfill gas, anaerobic digestion of organic waste, and energy production from non-recyclable waste fractions. The document aims to achieve climate goals aligned with the Paris Agreement by promoting sustainable waste management practices and reducing greenhouse gas emissions.', 'The sectoral technical document on waste management and emissions capture in Colombia outlines key activities for post-consumer waste management and greenhouse gas emissions capture essential for mitigating climate change and advancing towards a circular economy. It includes eligibility criteria for activities such as the use of non-hazardous waste material, capture and utilization of landfill gas, anaerobic digestion of organic waste, and energy production from non-recyclable waste fractions. The document aims to achieve climate goals aligned with the Paris Agreement by promoting sustainable waste management practices and reducing greenhouse gas emissions.', 'Colombia', 'climate', 'in_force', '2021-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_45', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'colombia', 'sdg12', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e78992e0-2128-5f42-991d-78efcd5e9fe2', 'Colombia Sectoral technical document: Water supple and treatment', 'Sectoral technical document: Water supple and treatment', 'This sectoral technical document on water supply and treatment in Colombia outlines the importance of domestic and industrial wastewater treatment for emissions reduction and climate change adaptation. It identifies economic activities and assets in the sector, including aqueduct systems, wastewater treatment systems, and desalination plants. The document sets eligibility criteria for improving energy efficiency, reducing water leaks, and increasing coverage of water supply systems. It emphasizes the role of drinking water supply and wastewater collection in mitigating climate change. The policy aims to promote sustainable practices and reduce greenhouse gas emissions in the water supply and treatment sector.', 'This sectoral technical document on water supply and treatment in Colombia outlines the importance of domestic and industrial wastewater treatment for emissions reduction and climate change adaptation. It identifies economic activities and assets in the sector, including aqueduct systems, wastewater treatment systems, and desalination plants. The document sets eligibility criteria for improving energy efficiency, reducing water leaks, and increasing coverage of water supply systems. It emphasizes the role of drinking water supply and wastewater collection in mitigating climate change. The policy aims to promote sustainable practices and reduce greenhouse gas emissions in the water supply and treatment sector.', 'This sectoral technical document on water supply and treatment in Colombia outlines the importance of domestic and industrial wastewater treatment for emissions reduction and climate change adaptation. It identifies economic activities and assets in the sector, including aqueduct systems, wastewater treatment systems, and desalination plants. The document sets eligibility criteria for improving energy efficiency, reducing water leaks, and increasing coverage of water supply systems. It emphasizes the role of drinking water supply and wastewater collection in mitigating climate change. The policy aims to promote sustainable practices and reduce greenhouse gas emissions in the water supply and treatment sector.', 'Colombia', 'climate', 'in_force', '2021-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_46', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'sdg6', 'colombia', 'sdg12', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('efc51521-f1b1-5d33-b801-499118c9e124', 'Colombia Sectoral technical document: Transport', 'Sectoral technical document: Transport', 'The Sectoral Technical Document on Transport in Colombia, prepared by the International Finance Corporation with support from Climate Bonds Initiative, aims to promote sustainable practices in the transport sector to combat climate change and transition to a low-carbon economy. It outlines eligibility criteria for urban public transport, micromobility, intercity transport, and private transport, focusing on reducing greenhouse gas emissions and promoting low-carbon transportation systems. The document emphasizes fleet renewal with low or zero-emission vehicles, alignment with sustainable mobility plans, and the importance of infrastructure for low-carbon transportation. It targets activities and assets related to urban, intercity, and private transport sectors.', 'The Sectoral Technical Document on Transport in Colombia, prepared by the International Finance Corporation with support from Climate Bonds Initiative, aims to promote sustainable practices in the transport sector to combat climate change and transition to a low-carbon economy. It outlines eligibility criteria for urban public transport, micromobility, intercity transport, and private transport, focusing on reducing greenhouse gas emissions and promoting low-carbon transportation systems. The document emphasizes fleet renewal with low or zero-emission vehicles, alignment with sustainable mobility plans, and the importance of infrastructure for low-carbon transportation. It targets activities and assets related to urban, intercity, and private transport sectors.', 'The Sectoral Technical Document on Transport in Colombia, prepared by the International Finance Corporation with support from Climate Bonds Initiative, aims to promote sustainable practices in the transport sector to combat climate change and transition to a low-carbon economy. It outlines eligibility criteria for urban public transport, micromobility, intercity transport, and private transport, focusing on reducing greenhouse gas emissions and promoting low-carbon transportation systems. The document emphasizes fleet renewal with low or zero-emission vehicles, alignment with sustainable mobility plans, and the importance of infrastructure for low-carbon transportation. It targets activities and assets related to urban, intercity, and private transport sectors.', 'Colombia', 'climate', 'in_force', '2021-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_47', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'sdg11', 'mandatory', 'colombia', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d74d6699-9924-59b9-bbd2-11262bae6337', 'Colombia Sectoral technical document: Information and communication technologies (ICT)', 'Sectoral technical document: Information and communication technologies (ICT)', 'The Sectoral technical document for Information and Communication Technologies (ICT) in Colombia outlines the essential role of ICT in supporting economic activities across various sectors like agriculture, energy, transportation, and construction. The document emphasizes the potential of ICT in advancing climate action through data centers, smart grids, and digital infrastructure. Eligibility criteria focus on energy efficiency, smart energy networks, and data-driven solutions for GHG reduction. The policy aims to promote sustainable development, improve public services, enhance disaster risk management, and reduce CO2 emissions through ICT innovations.', 'The Sectoral technical document for Information and Communication Technologies (ICT) in Colombia outlines the essential role of ICT in supporting economic activities across various sectors like agriculture, energy, transportation, and construction. The document emphasizes the potential of ICT in advancing climate action through data centers, smart grids, and digital infrastructure. Eligibility criteria focus on energy efficiency, smart energy networks, and data-driven solutions for GHG reduction. The policy aims to promote sustainable development, improve public services, enhance disaster risk management, and reduce CO2 emissions through ICT innovations.', 'The Sectoral technical document for Information and Communication Technologies (ICT) in Colombia outlines the essential role of ICT in supporting economic activities across various sectors like agriculture, energy, transportation, and construction. The document emphasizes the potential of ICT in advancing climate action through data centers, smart grids, and digital infrastructure. Eligibility criteria focus on energy efficiency, smart energy networks, and data-driven solutions for GHG reduction. The policy aims to promote sustainable development, improve public services, enhance disaster risk management, and reduce CO2 emissions through ICT innovations.', 'Colombia', 'climate', 'in_force', '2021-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_48', ARRAY['sdg2', 'sdg13', 'other sustainability policy', 'sdg7', 'sdg11', 'mandatory', 'colombia', 'mandatory_regulations', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('947aacbe-1be5-513a-94f1-fd8a5e443f48', 'Colombia Sectoral technical document: Manufacturing', 'Sectoral technical document: Manufacturing', 'The Sectoral technical document for Manufacturing in Colombia aims to establish a taxonomy of economic activities and assets within the manufacturing sector that contribute to low-carbon technologies and sustainable practices. It outlines eligibility criteria for manufacturing components, products, and technologies essential for renewable energy, sustainable transportation, and energy-efficient equipment. The document emphasizes the importance of sustainable manufacturing to achieve climate change goals and transition to a low-carbon economy. Mitigation measures must be incorporated into investment plans within specific timeframes to meet defined eligibility criteria.', 'The Sectoral technical document for Manufacturing in Colombia aims to establish a taxonomy of economic activities and assets within the manufacturing sector that contribute to low-carbon technologies and sustainable practices. It outlines eligibility criteria for manufacturing components, products, and technologies essential for renewable energy, sustainable transportation, and energy-efficient equipment. The document emphasizes the importance of sustainable manufacturing to achieve climate change goals and transition to a low-carbon economy. Mitigation measures must be incorporated into investment plans within specific timeframes to meet defined eligibility criteria.', 'The Sectoral technical document for Manufacturing in Colombia aims to establish a taxonomy of economic activities and assets within the manufacturing sector that contribute to low-carbon technologies and sustainable practices. It outlines eligibility criteria for manufacturing components, products, and technologies essential for renewable energy, sustainable transportation, and energy-efficient equipment. The document emphasizes the importance of sustainable manufacturing to achieve climate change goals and transition to a low-carbon economy. Mitigation measures must be incorporated into investment plans within specific timeframes to meet defined eligibility criteria.', 'Colombia', 'climate', 'in_force', '2021-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_49', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'sdg7', 'sdg11', 'mandatory', 'colombia', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b42fc7cd-8db5-5192-a2a4-2cb92dfd45b1', 'Colombia PHASE I FOR THE CONSTRUCTION OF THE GREEN', 'PHASE I FOR THE CONSTRUCTION OF THE GREEN TAXONOMY COLOMBIA TECHNICAL DOCUMENT No. 2 SECTORS: Livestock, Agriculture, Forestry', 'The Green Taxonomy of Colombia is a classification system of economic activities and assets that contribute to the achievement of the country''s environmental objectives and commitments. The Taxonomy incorporates a set of definitions aimed at supporting different actors in the public and private sector, such as bond issuers, investors, financial institutions, public entities, among others, in the identification and evaluation of investments that can meet environmental and that can be considered green or environmentally sustainable in Colombia.', 'The Green Taxonomy of Colombia is a classification system of economic activities and assets that contribute to the achievement of the country''s environmental objectives and commitments. The Taxonomy incorporates a set of definitions aimed at supporting different actors in the public and private sector, such as bond issuers, investors, financial institutions, public entities, among others, in the identification and evaluation of investments that can meet environmental and that can be considered green or environmentally sustainable in Colombia.', 'The Green Taxonomy of Colombia is a classification system of economic activities and assets that contribute to the achievement of the country''s environmental objectives and commitments. The Taxonomy incorporates a set of definitions aimed at supporting different actors in the public and private sector, such as bond issuers, investors, financial institutions, public entities, among others, in the identification and evaluation of investments that can meet environmental and that can be considered green or environmentally sustainable in Colombia.', 'Colombia', 'climate', 'in_force', '2021-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_50', ARRAY['sdg2', 'other sustainability policy', 'mandatory', 'colombia', 'mandatory_regulations', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5acbda24-7d2f-56f5-865f-1c7ddb5945e1', 'Technical Document of the Green Taxonomy Colombia Technical', 'Technical Document No. 2 of the Green Taxonomy Colombia Technical Annex A: Farming', 'The Technical Document No. 2 of the Green Taxonomy Colombia focuses on promoting sustainable livestock farming in Colombia by recognizing impacts and benefits across the production chain. The policy aims to improve productivity, product quality, competitiveness, ecosystem conservation, and climate adaptation. It details eligible investment categories, practices, and technologies for the livestock sector, transitioning towards a more sustainable production model. The document integrates experiences and knowledge to shift from conventional to comprehensive sustainability, involving national and international organizations'' support and consultation with industry representatives.', 'The Technical Document No. 2 of the Green Taxonomy Colombia focuses on promoting sustainable livestock farming in Colombia by recognizing impacts and benefits across the production chain. The policy aims to improve productivity, product quality, competitiveness, ecosystem conservation, and climate adaptation. It details eligible investment categories, practices, and technologies for the livestock sector, transitioning towards a more sustainable production model. The document integrates experiences and knowledge to shift from conventional to comprehensive sustainability, involving national and international organizations'' support and consultation with industry representatives.', 'The Technical Document No. 2 of the Green Taxonomy Colombia focuses on promoting sustainable livestock farming in Colombia by recognizing impacts and benefits across the production chain. The policy aims to improve productivity, product quality, competitiveness, ecosystem conservation, and climate adaptation. It details eligible investment categories, practices, and technologies for the livestock sector, transitioning towards a more sustainable production model. The document integrates experiences and knowledge to shift from conventional to comprehensive sustainability, involving national and international organizations'' support and consultation with industry representatives.', 'Colombia', 'climate', 'in_force', '2021-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_51', ARRAY['sdg2', 'sdg13', 'other sustainability policy', 'sdg9', 'mandatory', 'colombia', 'mandatory_regulations', 'sdg12', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('caeefc11-34dd-50cd-874e-7b091350db90', 'Technical Document of the Green Taxonomy Colombia Technical', 'Technical Document No. 2 of the Green Taxonomy Colombia Technical Annex A: Agriculture', 'The Technical Document No. 2 of the Green Taxonomy Colombia Technical Annex A: Agriculture, published in 2021 by Colombia, focuses on analyzing the environmental sustainability of agriculture. It outlines goals impacting the agricultural sector, investment categories, and eligible practices and technologies to promote green taxonomy. The document emphasizes organic farming, ecosystem restoration, and climate intelligence for resilient, low-carbon production. It addresses challenges like water management, soil fertility, and agrochemical use, aiming to enhance agricultural sustainability and reduce environmental degradation.', 'The Technical Document No. 2 of the Green Taxonomy Colombia Technical Annex A: Agriculture, published in 2021 by Colombia, focuses on analyzing the environmental sustainability of agriculture. It outlines goals impacting the agricultural sector, investment categories, and eligible practices and technologies to promote green taxonomy. The document emphasizes organic farming, ecosystem restoration, and climate intelligence for resilient, low-carbon production. It addresses challenges like water management, soil fertility, and agrochemical use, aiming to enhance agricultural sustainability and reduce environmental degradation.', 'The Technical Document No. 2 of the Green Taxonomy Colombia Technical Annex A: Agriculture, published in 2021 by Colombia, focuses on analyzing the environmental sustainability of agriculture. It outlines goals impacting the agricultural sector, investment categories, and eligible practices and technologies to promote green taxonomy. The document emphasizes organic farming, ecosystem restoration, and climate intelligence for resilient, low-carbon production. It addresses challenges like water management, soil fertility, and agrochemical use, aiming to enhance agricultural sustainability and reduce environmental degradation.', 'Colombia', 'climate', 'in_force', '2021-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_52', ARRAY['sdg2', 'sdg13', 'other sustainability policy', 'mandatory', 'sdg6', 'colombia', 'mandatory_regulations', 'sdg12', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8ff67cf9-deed-5d8b-aebf-960811cafc00', 'Technical Document of the Green Taxonomy Colombia Technical', 'Technical Document No. 2 of the Green Taxonomy Colombia Technical Annex A: Forestry', 'The Technical Document No. 2 of the Green Taxonomy Colombia outlines sustainability practices for the forestry sector, emphasizing conservation and commercial use of forests. It defines sustainable forestry work, investment categories, and technologies eligible for the sector. The policy aims to align forestry practices with Colombia''s regulations, preserve natural heritage, and unlock economic potential. By promoting sustainable forest management plans and emphasizing the social, environmental, and economic dimensions of forests, the policy seeks to bridge the gap between forestry potential and societal benefits.', 'The Technical Document No. 2 of the Green Taxonomy Colombia outlines sustainability practices for the forestry sector, emphasizing conservation and commercial use of forests. It defines sustainable forestry work, investment categories, and technologies eligible for the sector. The policy aims to align forestry practices with Colombia''s regulations, preserve natural heritage, and unlock economic potential. By promoting sustainable forest management plans and emphasizing the social, environmental, and economic dimensions of forests, the policy seeks to bridge the gap between forestry potential and societal benefits.', 'The Technical Document No. 2 of the Green Taxonomy Colombia outlines sustainability practices for the forestry sector, emphasizing conservation and commercial use of forests. It defines sustainable forestry work, investment categories, and technologies eligible for the sector. The policy aims to align forestry practices with Colombia''s regulations, preserve natural heritage, and unlock economic potential. By promoting sustainable forest management plans and emphasizing the social, environmental, and economic dimensions of forests, the policy seeks to bridge the gap between forestry potential and societal benefits.', 'Colombia', 'nature', 'in_force', '2021-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_53', ARRAY['sdg2', 'other sustainability policy', 'mandatory', 'colombia', 'mandatory_regulations', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
